DROP TABLE IF EXISTS `usuarios`;
CREATE TABLE IF NOT EXISTS `usuarios` (
  `id` int NOT NULL AUTO_INCREMENT,
  `cedula` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sexo` enum('M','F','O') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'M',
  `fechnac` date DEFAULT NULL,
  `email` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `celular` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Número de teléfono/celular del usuario',
  `recovery_token` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `username` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role` enum('admin_general','admin_torneo','admin_club','usuario') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'usuario',
  `status` enum('pending','approved','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `email_verificado` tinyint(1) DEFAULT '0' COMMENT 'Indica si el email fue verificado',
  `email_verification_token` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Token para verificación de email',
  `email_verified_at` timestamp NULL DEFAULT NULL COMMENT 'Fecha de verificación del email',
  `recovery_token_expires` timestamp NULL DEFAULT NULL,
  `last_login` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  KEY `idx_cedula` (`cedula`),
  KEY `idx_status` (`status`),
  KEY `idx_email` (`email`),
  KEY `idx_username` (`username`),
  KEY `fk_approved_by` (`approved_by`),
  KEY `idx_celular` (`celular`)
) ENGINE=InnoDB AUTO_INCREMENT=169 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;





